// Sales tab: Date, Bill no, Customer, Amount, Mode (cash/UPI/card)   Expenses tab: Date, Vendor, Amount, Category, Mode
const num = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const S = $('Today\'s sales').all().map(i => i.json).filter(r => r.Amount !== undefined && r.Amount !== '');
const E = $('Today\'s expenses').all().map(i => i.json).filter(r => r.Amount !== undefined && r.Amount !== '');
const sum = (a, f = () => true) => a.filter(f).reduce((s, r) => s + num(r.Amount), 0);
const by = (a, k) => a.reduce((m, r) => (m[r[k] || 'Other'] = (m[r[k] || 'Other'] || 0) + num(r.Amount), m), {});
const sales = sum(S), spent = sum(E);
return [{ json: { date: $now.setZone('Asia/Kolkata').toFormat('d LLL yyyy'), bills: S.length, sales, spent, net: sales - spent,
  sales_by_mode: by(S, 'Mode'), spend_by_category: by(E, 'Category'), cash_in: sum(S, r => String(r.Mode).toLowerCase() === 'cash'), cash_out: sum(E, r => String(r.Mode).toLowerCase() === 'cash'),
  biggest_expense: E.sort((a, b) => num(b.Amount) - num(a.Amount))[0] || null } }];

